                final long playingFor = data.getLong("TickCount") - data.getLong("RecordStartTick");

                data.remove("IsPlaying");
                data.remove("TickCount");
                data.remove("RecordStartTick");

                if (playingFor > 0L) {
                    data.setLong("ticks_since_song_started", playingFor);
                }

                return null;
            }
        });
    }

